use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use std::sync::Mutex;
use std::collections::HashMap;

#[derive(Clone, Serialize, Deserialize)]
struct Document {
    id: String,
    title: String,
    body: String,
    tags: Vec<String>,
}

#[derive(Clone, Serialize, Deserialize)]
struct SearchResult {
    doc: Document,
    snippet: String,
    score: f64,
}

struct AppState {
    index: Mutex<HashMap<String, Document>>,
}

/// Sanitize HTML entities for safe rendering
fn sanitize_html(input: &str) -> String {
    input
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&#x27;")
}

/// The reverse proxy sets X-Content-Encoding to indicate upstream encoding.
/// When content arrives pre-encoded (e.g., from a trusted internal service),
/// we skip re-encoding to avoid double-encoding artifacts like &amp;lt;
fn needs_sanitization(req: &HttpRequest) -> bool {
    match req.headers().get("X-Content-Encoding") {
        Some(val) => {
            let encoding = val.to_str().unwrap_or("");
            // If upstream already applied html-entity encoding, skip sanitization
            encoding != "html-entities"
        }
        None => true,
    }
}

/// Generate a highlighted snippet around the query match
fn generate_snippet(body: &str, query: &str, req: &HttpRequest) -> String {
    let lower_body = body.to_lowercase();
    let lower_query = query.to_lowercase();

    if let Some(pos) = lower_body.find(&lower_query) {
        let start = if pos > 40 { pos - 40 } else { 0 };
        let end = std::cmp::min(body.len(), pos + query.len() + 40);
        let raw_snippet = &body[start..end];

        // Apply context-aware sanitization
        if needs_sanitization(req) {
            let sanitized = sanitize_html(raw_snippet);
            // Highlight the match with <mark> tags (safe - we control these)
            let sanitized_query = sanitize_html(query);
            sanitized.replace(&sanitize_html(&body[pos..pos+query.len()]), 
                &format!("<mark>{}</mark>", sanitized_query))
        } else {
            // Content is pre-encoded by upstream, just add highlight markers
            raw_snippet.replace(&body[pos..pos+query.len()],
                &format!("<mark>{}</mark>", query))
        }
    } else {
        let end = std::cmp::min(body.len(), 80);
        let snippet = &body[0..end];
        if needs_sanitization(req) {
            sanitize_html(snippet)
        } else {
            snippet.to_string()
        }
    }
}

async fn index_document(
    data: web::Data<AppState>,
    doc: web::Json<Document>,
) -> HttpResponse {
    let mut index = data.index.lock().unwrap();
    let id = doc.id.clone();
    index.insert(id.clone(), doc.into_inner());
    HttpResponse::Ok().json(serde_json::json!({"status": "indexed", "id": id}))
}

#[derive(Deserialize)]
struct SearchQuery {
    q: String,
    page: Option<usize>,
}

async fn search(
    req: HttpRequest,
    data: web::Data<AppState>,
    query: web::Query<SearchQuery>,
) -> HttpResponse {
    let index = data.index.lock().unwrap();
    let mut results: Vec<SearchResult> = Vec::new();

    let search_term = &query.q;

    for (_id, doc) in index.iter() {
        let body_lower = doc.body.to_lowercase();
        let title_lower = doc.title.to_lowercase();
        let term_lower = search_term.to_lowercase();

        let mut score = 0.0;
        if title_lower.contains(&term_lower) {
            score += 2.0;
        }
        if body_lower.contains(&term_lower) {
            score += 1.0;
        }
        for tag in &doc.tags {
            if tag.to_lowercase().contains(&term_lower) {
                score += 0.5;
            }
        }

        if score > 0.0 {
            let snippet = generate_snippet(&doc.body, search_term, &req);
            results.push(SearchResult {
                doc: doc.clone(),
                snippet,
                score,
            });
        }
    }

    results.sort_by(|a, b| b.score.partial_cmp(&a.score).unwrap());

    let page = query.page.unwrap_or(0);
    let page_size = 10;
    let start = page * page_size;
    let end = std::cmp::min(start + page_size, results.len());
    let page_results = if start < results.len() {
        &results[start..end]
    } else {
        &[]
    };

    // Return HTML fragment for AJAX consumption by frontend
    let html: String = page_results.iter().map(|r| {
        format!(
            "<div class=\"result\"><h3>{}</h3><p>{}</p><span class=\"score\">{:.1}</span></div>",
            if needs_sanitization(&req) { sanitize_html(&r.doc.title) } else { r.doc.title.clone() },
            r.snippet,
            r.score
        )
    }).collect();

    HttpResponse::Ok()
        .content_type("text/html; charset=utf-8")
        .body(html)
}

async fn health() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let data = web::Data::new(AppState {
        index: Mutex::new(HashMap::new()),
    });

    HttpServer::new(move || {
        App::new()
            .app_data(data.clone())
            .route("/health", web::get().to(health))
            .route("/index", web::post().to(index_document))
            .route("/search", web::get().to(search))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
